# F4 LabelGovernor
for _needle in ("GetDescendants", "RenderStepped", "AlwaysOnTop = true", "FireServer", "InvokeServer"):
    must_not_contain(G_LG, _needle, f"F4 LabelGovernor: no {_needle}")
